(1,'versPHP','Affiche la version de Php','<?php\r\nphpinfo();','[xyz-ips snippet=\"versPHP\"]',1,2,0,0),
(2,'requetteSQL','','<?php\r\n// Select contient la requête SQL\r\n$select = \"SELECT post_title, guid, post_date FROM wp_posts WHERE\r\npost_type=\'page\'\";\r\n// Exécute cette requête sur la base de donnée Wordpress représentée par $wpdb\r\n$resultats = $wpdb->get_results($select);\r\n// La commande echo dit à php d\'écrire <table> dans le code html qu\'il génère\r\necho \"<table border=1>\";\r\n// Pour chaque $ligne de mon tableau $resultats\r\nforeach($resultats as $ligne){\r\n// Ecrire <tr><td> dans mon code html\r\n    echo \"<tr><td>\";\r\n    // Ecrire le champ post_title\r\n    echo $ligne->post_title;\r\n    // Passe à la colonne suivante\r\n    echo \"</td><td>\";\r\n    // Ecrire le champ post_date\r\n    echo $ligne->post_date;\r\n    // Passe à la colonne suivante\r\n    echo \"</td><td>\";\r\n    // Créer un lien\r\n    echo \"<a href=\";\r\n    echo $ligne->guid;\r\n    echo \">lien</a>\";\r\n    // Passe à la ligne suivante\r\n    echo \"</td></tr><br>\";\r\n    }\r\n// Fin de la table\r\necho \"</table>\";','[xyz-ips snippet=\"requetteSQL\"]',1,2,0,0),
(3,'contact','','<?php\r\nglobal $wpdb;\r\n\r\n// Exécute le code si le bouton ajouter est cliqué\r\nif (isset($_POST[\'ajouter\'])) {\r\n\r\n    // Récupération directe des données du formulaire sans filtrage\r\n    $nom   = $_POST[\'nom\'];\r\n    $email = $_POST[\'email\'];\r\n    $objet = $_POST[\'objet\'];\r\n\r\n    // Construction de la requête SQL en concaténation directe (Vulnérable aux injections)\r\n    // On suppose que ta table s\'appelle \'contact\'\r\n    $sql = \"INSERT INTO contact (nom, email, objet) VALUES (\'$nom\', \'$email\', \'$objet\')\";\r\n\r\n    // Exécution de la requête\r\n    $wpdb->query($sql);\r\n\r\n    // Affichage de la requête pour tes tests\r\n    echo \"Requête : $sql\";\r\n}\r\n?>','[xyz-ips snippet=\"contact\"]',1,2,0,0);
/*!40000 ALTER TABLE `wp_xyz_ips_short_code` ENABLE KEYS */;
UNLOCK TABLES;
COMMIT;
